@dataclass(frozen=True)
class Depends:
    dependency: Callable[..., Any] | None = None
    use_cache: bool = True
    scope: Literal["function", "request"] | None = None
    max_concurrency: int | None = field(default=None, kw_only=True)
    _concurrency: _DependencyConcurrency | None = field(
        default=None, repr=False, kw_only=True
    )

    def __post_init__(self) -> None:
        if self.max_concurrency is None:
            object.__setattr__(self, "_concurrency", None)
            return

def _get_cache_key(
    *,
    dependant: Dependant,
    uses_scopes_cache: _UsesScopesCache | None = None,
) -> DependencyCacheKey:
    scopes_for_cache = (
        tuple(sorted(set(_get_oauth_scopes(dependant=dependant))))
        if _uses_scopes(dependant=dependant, cache=uses_scopes_cache)
        else ()
    )
    return (
        dependant.call,
        scopes_for_cache,
        _get_computed_scope(dependant=dependant) or "",
    )

def get_dependant(*, path: str, call: Callable, ...) -> Dependant:
    dependant = Dependant(call=call, name=name, path=path, ...)
    path_param_names = get_path_param_names(path)
    endpoint_signature = get_typed_signature(call)
    for param_name, param in endpoint_signature.parameters.items():
        param_details = analyze_param(param_name=param_name, ...)
        if param_details.depends is not None:
            sub_dependant = get_dependant(path=path, call=..., ...)
            dependant.dependencies.append(sub_dependant)
            continue
        if add_non_field_param_to_dependency(...):
            continue
        if isinstance(param_details.field.field_info, params.Body):
            dependant.body_params.append(param_details.field)
    return dependant

def analyze_param(*, param_name, annotation, value, path_param_names):
    is_path_param = param_name in path_param_names
    field_info = None; depends = None
    if get_origin(use_annotation) is Annotated:
        type_annotation = get_args(annotation)[0]
        fastapi_annotations = [
            a for a in get_args(annotation)[1:]
            if isinstance(a, (FieldInfo, params.Depends))]
    if isinstance(value, params.Depends):
        depends = value
    elif isinstance(value, FieldInfo):
        field_info = value
    return ParamDetails(type_annotation, depends, field)

async def solve_dependencies(
    *, request, dependant, body, ..., dependency_cache, embed_body_fields
) -> SolvedDependency:
    for sub_dependant in dependant.dependencies:
        if sub_dependant.use_cache and sub_dependant_cache_key in dependency_cache:
            solved = dependency_cache[sub_dependant_cache_key]
        elif _is_gen_callable(use_sub_dependant.call) or _is_async_gen_callable(...):
            solved = await _solve_generator(request=request, dependant=use_sub_dependant, stack=use_astack, ...)
        elif _is_coroutine_callable(use_sub_dependant.call):
            solved = await call(**solved_result.values)
        else:
            solved = await run_in_threadpool(call, **solved_result.values)
    path_values, path_errors = request_params_to_args(dependant.path_params, request.path_params)
    return SolvedDependency(values=values, errors=errors, ...)

def request_params_to_args(
    fields: Sequence[ModelField],
    received_params: Mapping[str, Any] | QueryParams | Headers,
) -> tuple[dict[str, Any], list[Any]]:
    values: dict[str, Any] = {}
    errors: list[Any] = []
    for field in fields:
        if (model := _get_param_model(field)) is not None:
            v_, errors_ = _request_param_model_to_args(field, model, received_params)
        else:
            aliases = _get_param_aliases(field)
            value = _get_multidict_value(field, received_params, alias=alias)
            v_, errors_ = _validate_value_with_model_field(field=field, ...)
    return values, errors

async def _solve_generator(
    *, dependant, stack, sub_values, request
) -> Any:
    if _is_async_gen_callable(dependant.call):
        cm = asynccontextmanager(dependant.call)(**sub_values)
        cleanup_scopes = request.scope.setdefault("fastapi_async_cleanup_scopes", {})
        request_stack = cast(AsyncExitStack, request.scope["fastapi_inner_astack"])
        cleanup_scope = cleanup_scopes.get(request_stack)
        if cleanup_scope is None:
            cleanup_scope = request_stack.enter_context(CancelScope())
        cm = _asynccontextmanager_with_shielded_exit(cm, cleanup_scope)
    elif _is_gen_callable(dependant.call):
        cm = contextmanager_in_threadpool(contextmanager(dependant.call)(**sub_values))
    return await stack.enter_async_context(cm)

